                    "sql": "CREATE OR REPLACE TABLE snitch_db.maplemonk.unicommerce_fact_items_intermediate_2024 AS WITH ranked_data AS ( SELECT \"Channel Name\" AS MARKETPLACE, CASE WHEN UPPER(TRIM(\"Channel Name\")) LIKE \'%CRED%\' THEN \'CRED\' WHEN UPPER(TRIM(\"Channel Name\")) LIKE \'%FLIPKART%\' THEN \'FLIPKART\' WHEN UPPER(TRIM(\"Channel Name\")) LIKE \'%MYNTRA%\' THEN \'MYNTRA\' WHEN UPPER(TRIM(\"Channel Name\")) LIKE \'%AJIO%\' THEN \'AJIO\' WHEN UPPER(TRIM(\"Channel Name\")) LIKE \'%STORE%\' THEN \'STORE\' WHEN UPPER(TRIM(\"Channel Name\")) LIKE \'%AMAZON%\' THEN \'AMAZON\' WHEN UPPER(TRIM(\"Channel Name\")) LIKE \'%DONOSHOP%\' THEN \'POPCLUB\' ELSE \"Channel Name\" END AS MARKETPLACE_MAPPED, \"Display Order Code\" AS order_name, CASE WHEN marketplace_mapped = \'SHOPIFY\' THEN SUBSTRING(\"Sale Order Code\", 2, LENGTH(\"Sale Order Code\") - 1) ELSE \"Sale Order Code\" END AS order_id, \"Notification Email\" AS EMAIL, \"Notification Mobile\" AS PHONE, \"Shipping Address Phone\" AS SHIPPING_ADDRESS_PHONE, \"Shipping Address Name\" AS NAME, \"Fulfillment TAT\" AS FULFILLMENT_TAT, NULLIF(CREATED, \'\')::TIMESTAMP AS UC_CREATED, NULLIF(UPDATED, \'\')::DATE AS SHIPPING_LAST_UPDATE_DATE, NULLIF(UPDATED, \'\')::TIMESTAMP AS SHIPPING_LAST_UPDATE_TIMESTAMP, \"Item SKU Code\" AS SKU, LEFT(\"Item SKU Code\", LENGTH(\"Item SKU Code\") - CHARINDEX(\'-\', REVERSE(\"Item SKU Code\"))) AS SKU_GROUP, \"Channel Product Id\" AS PRODUCT_ID, CASE WHEN \"Sale Order Item Status\" LIKE \'PICKING_%\' THEN \"Shipping Package Status Code\" ELSE \"Sale Order Item Status\" END AS SALE_ORDER_ITEM_STATUS, \"Item Details\" AS ITEM_DETAILS, \"Shipping Address Line 1\" AS ADDRESS_LINE_1, \"Shipping Address Line 2\" AS ADDRESS_LINE_2, \"Shipping Address City\" AS CITY, \"Shipping Address State\" AS STATE, \"Shipping Address Country\" AS COUNTRY, \"Shipping Address Pincode\" AS PINCODE, \"Sale Order Status\" AS ORDER_STATUS, NULLIF(\"Order Date as dd/mm/yyyy hh:MM:ss\", \'\')::DATE AS ORDER_DATE, NULLIF(\"Order Date as dd/mm/yyyy hh:MM:ss\", \'\')::TIMESTAMP AS ORDER_TIMESTAMP, NULLIF(\"Shipping Package Creation Date\", \'\')::TIMESTAMP AS SHIPPING_PACKAGE_CREATED, \'1\' AS SUBORDER_QUANTITY, coalesce(nullif(discount,\'\'),0) AS DISCOUNT, \"Tax Value\" AS TAX, coalesce(nullif(\"Selling Price\",\'\'),0) AS SELLING_PRICE, NULLIF(\"Shipping Package Code\", \'\') AS SHIPPINGPACKAGECODE, \"Shipping Package Status Code\" AS SHIPPINGPACKAGESTATUS, facility AS WAREHOUSE_NAME, CASE WHEN marketplace_mapped = \'SHOPIFY\' THEN SUBSTRING(\"Sale Order Item Code\", 2, LENGTH(\"Sale Order Item Code\") - 1) ELSE \"Sale Order Item Code\" END AS SALEORDERITEMCODE, coalesce(nullif(mrp,\'\'),0) AS MRP, discountcode as DISCOUNT_CODE, \"Shipping provider\" AS COURIER, \"Shipping Tracking Status\" AS SHIPPING_STATUS, NULLIF(\"Shipping Package Creation Date\", \'\')::DATE AS CREATED_TIMESTAMP, NULLIF(\"Packing Time\", \'\')::DATE AS PACKED_TIMESTAMP, NULLIF(\"Dispatch Date\", \'\')::DATE AS DISPATCH_DATE, NULLIF(\"Dispatch Date\", \'\')::TIMESTAMP AS DISPATCHED_TIMESTAMP, NULLIF(\"Delivery Time\", \'\')::DATE AS DELIVERED_DATE, NULLIF(\"Delivery Time\", \'\')::TIMESTAMP AS DELIVERED_TIMESTAMP, category, \"Cost Price\" AS COST, \"Invoice Code\" as INVOICE_CODE, NULLIF(\"Invoice Created\", \'\')::TIMESTAMP AS INVOICE_DATE, \"Tracking Number\" AS AWB, \"Shipping Courier\" AS SHIPPING_COURIER, ROW_NUMBER() OVER (PARTITION BY \"Sale Order Item Code\" ORDER BY NULLIF(UPDATED, \'\') DESC) AS row_num, \"On Hold\" as ON_HOLD, \"Shipping Package Type\" AS SHIPPING_PACKAGE_TYPE, \"Reverse Pickup Code\" as REVERSE_PICKUP_CODE, \"Reverse Pickup Created Date\" as REVERSE_PICKUP_CREATED, \"Notification Email\" as NOTIFICATION_EMAIL, \"Notification Mobile\" as NOTIFICATION_MOBILE, \"Require Customization\" as CUSTOMIZATION, COD, \"Shipping Address Id\" as SHIPPING_ID, \"Cancellation Reason\" as CANCELLATION_REASON, \"Shipping Arranged By\" as SHIPPING_ARRANGED_BY, \"Length(mm)\" as PACKAGE_LENGTH, \"Width(mm)\" as PACKAGE_WIDTH, \"Height(mm)\" as PACKAGE_HEIGHT, \"Return Date\" as RETURN_DATE, \"Return Reason\" as RETURN_REASON, \"Return Remarks\" as RETURN_REMARKS, \"Item Code\" as ITEM_CODE, weight, \"SKU Name\" as SKU_NAME, \"Shipping Courier Status\" as SHIPPING_COURIER_STATUS, \"Shipping Tracking Status\" as SHIPPING_TRACKING_STATUS, \"Packing Time\" as PACKED_TIME, \"Packing User\" as PACKING_USER, CASE WHEN SHIPPING_COURIER_STATUS in (\'COURIER_RETURN-CREATED\',\'COURIER_RETURN-RETURN_CREATED\',\'COURIER_RETURN-CONFIRMED\') then \'DTO-INPROCESS\' WHEN SHIPPING_COURIER_STATUS like \'%ORIGIN%\' then \'RTO\' WHEN SHIPPING_COURIER_STATUS like \'%COURIER_RETURN%\' then \'DTO\' WHEN SHIPPING_COURIER_STATUS in (\'DISPATCHED\',\'PICKED\',\'SHIPPED\',\'PENDING\') then \'INTRANSIT\' WHEN SHIPPING_COURIER_STATUS like \'%REFUSED_TO_ACCEPT%\' then \'RTO\' WHEN SHIPPING_COURIER_STATUS in (\'DELIVERED\') then \'DELIVERED\' when DISPATCH_DATE is null and SALE_ORDER_ITEM_STATUS like \'%CAN%\' then \'CANCELLED\' when SALE_ORDER_ITEM_STATUS in (\'CREATED\', \'MANIFESTED\', \'PICKING\', \'PICKED\', \'PACKED\', \'READY_TO_SHIP\', \'PICKING_FOR_INVOICING\', \'FULFILLABLE\',\'DISPATCHED\',\'SHIPPED\',\'UNFULFILLABLE\',\'PENDING_CUSTOMIZATION\') THEN \'PROCESSING\' END AS ITEM_FINAL_STATUS FROM snitch_db.maplemonk.Snitch_uc_New_get_sale_orders where \"Require Customization\" not in (\'STD\') ) SELECT * FROM ranked_data WHERE row_num = 1;",
